From d40b1e0244a5be7a44815398cfd391b79bf0dfc3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 00:34:15 +0100
Subject: [PATCH] applets/taskmanager: always show all Places in the context
 menu
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

A running file manager's context menu only listed five Places plus a "N
more Places…" entry that reopened the menu, which made reaching a Place
slower than opening the app. Show all of them, as launchers already do.

BUG: 440282
---
 applets/taskmanager/backend.cpp         | 18 +-----------------
 applets/taskmanager/backend.h           |  4 +---
 applets/taskmanager/qml/ContextMenu.qml | 17 +----------------
 applets/taskmanager/qml/Task.qml        | 10 +---------
 4 files changed, 4 insertions(+), 45 deletions(-)

diff --git a/applets/taskmanager/backend.cpp b/applets/taskmanager/backend.cpp
index 1005d2a981..4d13b61641 100644
--- a/applets/taskmanager/backend.cpp
+++ b/applets/taskmanager/backend.cpp
@@ -245,7 +245,7 @@ QVariantList Backend::systemSettingsActions(QObject *parent) const
     return actions;
 }

-QVariantList Backend::placesActions(const QUrl &launcherUrl, bool showAllPlaces, QObject *parent)
+QVariantList Backend::placesActions(const QUrl &launcherUrl, QObject *parent)
 {
     if (!parent) {
         return QVariantList();
@@ -325,22 +325,6 @@ QVariantList Backend::placesActions(const QUrl &launcherUrl, bool showAllPlaces,
         }
     }

-    // There is nothing more frustrating than having a "More" entry that ends up showing just one or two
-    // additional entries. Therefore we truncate to max. 5 entries only if there are more than 7 in total.
-    if (!showAllPlaces && actions.count() > 7) {
-        const int totalActionCount = actions.count();
-
-        while (actions.count() > 5) {
-            actions.removeLast();
-        }
-
-        QAction *action = new QAction(parent);
-        action->setIcon(QIcon::fromTheme(QStringLiteral("view-more-symbolic")));
-        action->setText(i18ncp("Show all user Places", "%1 more Place…", "%1 more Places…", totalActionCount - actions.count()));
-        connect(action, &QAction::triggered, this, &Backend::showAllPlaces);
-        actions << QVariant::fromValue(action);
-    }
-
     return actions;
 }

diff --git a/applets/taskmanager/backend.h b/applets/taskmanager/backend.h
index f95faee70b..3004ac589e 100644
--- a/applets/taskmanager/backend.h
+++ b/applets/taskmanager/backend.h
@@ -55,7 +55,7 @@ public:
     ~Backend() override;

     Q_INVOKABLE QVariantList jumpListActions(const QUrl &launcherUrl, QObject *parent);
-    Q_INVOKABLE QVariantList placesActions(const QUrl &launcherUrl, bool showAllPlaces, QObject *parent);
+    Q_INVOKABLE QVariantList placesActions(const QUrl &launcherUrl, QObject *parent);
     Q_INVOKABLE QVariantList recentDocumentActions(const QUrl &launcherUrl, QObject *parent);
     Q_INVOKABLE void setActionGroup(QAction *action) const;

@@ -80,8 +80,6 @@ public:
 Q_SIGNALS:
     void addLauncher(const QUrl &url) const;

-    void showAllPlaces();
-
     void screenChanged();
     void hasActiveTaskChanged();
     void showsOnlyCurrentScreenChanged();
diff --git a/applets/taskmanager/qml/ContextMenu.qml b/applets/taskmanager/qml/ContextMenu.qml
index fe837049fc..8799f2ec8e 100644
--- a/applets/taskmanager/qml/ContextMenu.qml
+++ b/applets/taskmanager/qml/ContextMenu.qml
@@ -25,8 +25,6 @@ PlasmaExtras.Menu {

     readonly property var atm: TaskManager.AbstractTasksModel

-    property bool showAllPlaces: false
-
     placement: {
         if (Plasmoid.location === PlasmaCore.Types.LeftEdge) {
             return PlasmaExtras.Menu.RightPosedTopAlignedPopup;
@@ -50,19 +48,6 @@ PlasmaExtras.Menu {
         }
     }

-    Component.onCompleted: {
-        // Cannot have "Connections" as child of PlasmaExtras.Menu.
-        backend.showAllPlaces.connect(showContextMenuWithAllPlaces);
-    }
-
-    Component.onDestruction: {
-        backend.showAllPlaces.disconnect(showContextMenuWithAllPlaces);
-    }
-
-    function showContextMenuWithAllPlaces(): void {
-        (visualParent as Task).showContextMenu({showAllPlaces: true});
-    }
-
     function get(modelProp: int): var {
         return tasksModel.data(modelIndex, modelProp)
     }
@@ -93,7 +78,7 @@ PlasmaExtras.Menu {
     function loadDynamicLaunchActions(launcherUrl: url): void {
         let sections = [];

-        const placesActions = backend.placesActions(launcherUrl, showAllPlaces, menu);
+        const placesActions = backend.placesActions(launcherUrl, menu);

         if (placesActions.length > 0) {
             sections.push({
diff --git a/applets/taskmanager/qml/Task.qml b/applets/taskmanager/qml/Task.qml
index 90530078c5..54ae283876 100644
--- a/applets/taskmanager/qml/Task.qml
+++ b/applets/taskmanager/qml/Task.qml
@@ -395,15 +395,7 @@ PlasmaCore.ToolTipArea {
         acceptedButtons: Qt.LeftButton
         acceptedDevices: PointerDevice.TouchScreen | PointerDevice.Stylus
         gesturePolicy: TapHandler.ReleaseWithinBounds
-        onLongPressed: {
-            // When we're a launcher, there's no window controls, so we can show all
-            // places without the menu getting super huge.
-            if (task.model.IsLauncher) {
-                task.showContextMenu({showAllPlaces: true})
-            } else {
-                task.showContextMenu();
-            }
-        }
+        onLongPressed: task.showContextMenu()
     }

     TapHandler {
